/* Binary assets linked into the ELF; generated by tools/build_*.py. */
    .section .rodata
    .balign 32
    .global _jp_textures_pak
_jp_textures_pak:
    .incbin "assets/generated/textures.pak"

    .balign 32
    .global _jp_sfx_pak
_jp_sfx_pak:
    .incbin "assets/generated/sfx.pak"

    .balign 32
    .global _jp_music_adpcm
    .global _jp_music_adpcm_end
_jp_music_adpcm:
    .incbin "assets/generated/bazaar_music.adpcm"
_jp_music_adpcm_end:
    .balign 32
